1	import { Router, type Request, type Response } from "express";
2	import type { Db } from "@paperclipai/db";
3	import { upsertSidebarOrderPreferenceSchema } from "@paperclipai/shared";
4	import { validate } from "../middleware/validate.js";
5	import { logActivity, sidebarPreferenceService } from "../services/index.js";
6	import { assertBoard, assertCompanyAccess, getActorInfo } from "./authz.js";
7	
8	function requireBoardUserId(req: Request, res: Response): string | null {
9	  assertBoard(req);
10	  if (!req.actor.userId) {
11	    res.status(403).json({ error: "Board user context required" });
12	    return null;
13	  }
14	  return req.actor.userId;
15	}
16	
17	export function sidebarPreferenceRoutes(db: Db) {
18	  const router = Router();
19	  const svc = sidebarPreferenceService(db);
20	
21	  router.get("/sidebar-preferences/me", async (req, res) => {
22	    const userId = requireBoardUserId(req, res);
23	    if (!userId) return;
24	    res.json(await svc.getCompanyOrder(userId));
25	  });
26	
27	  router.put("/sidebar-preferences/me", validate(upsertSidebarOrderPreferenceSchema), async (req, res) => {
28	    const userId = requireBoardUserId(req, res);
29	    if (!userId) return;
30	    res.json(await svc.upsertCompanyOrder(userId, req.body.orderedIds));
31	  });
32	
33	  router.get("/companies/:companyId/sidebar-preferences/me", async (req, res) => {
34	    const companyId = req.params.companyId as string;
35	    assertCompanyAccess(req, companyId);
36	    const userId = requireBoardUserId(req, res);
37	    if (!userId) return;
38	    res.json(await svc.getProjectOrder(companyId, userId));
39	  });
40	
41	  router.put(
42	    "/companies/:companyId/sidebar-preferences/me",
43	    validate(upsertSidebarOrderPreferenceSchema),
44	    async (req, res) => {
45	      const companyId = req.params.companyId as string;
46	      assertCompanyAccess(req, companyId);
47	      const userId = requireBoardUserId(req, res);
48	      if (!userId) return;
49	
50	      const result = await svc.upsertProjectOrder(companyId, userId, req.body.orderedIds);
51	      const actor = getActorInfo(req);
52	      await logActivity(db, {
53	        companyId,
54	        actorType: actor.actorType,
55	        actorId: actor.actorId,
56	        agentId: actor.agentId,
57	        runId: actor.runId,
58	        action: "sidebar_preferences.project_order_updated",
59	        entityType: "company",
60	        entityId: companyId,
61	        details: {
62	          userId,
63	          orderedIds: result.orderedIds,
64	        },
65	      });
66	      res.json(result);
67	    },
68	  );
69	
70	  return router;
71	}
